-- Generated by scripts/seed_report.py from content/report.yaml.
-- Do not edit: run the script and commit what it writes.
--
-- Repeatable. Missing pieces are inserted; pieces still marked `placeholder`
-- are replaced with whatever the file now says. A piece somebody has edited by
-- hand — `placeholder` cleared — is never touched again.
ON CONFLICT (kind, archetype_id, dimension, band, section) DO UPDATE
SET text = EXCLUDED.text,
    placeholder = EXCLUDED.placeholder
WHERE report_pieces.placeholder;
